// spec fn count_eligible(participations: Seq<int>, k: int) -> int

pub fn solve(n: u8, k: u8, participations: Vec<u8>) -> u8 {
    // Consider only the first min(n, participations.len()) elements
    let limit = std::cmp::min(n as usize, participations.len());

    // Eligibility: 5 - attendance >= k  <=> attendance <= 5 - k
    // Safe because k in [0,5], so (5 - k) stays in [0,5].
    let threshold = 5u8.saturating_sub(k);

    let mut eligible: u8 = 0;
    for &a in participations.iter().take(limit) {
        // a is assumed to be in 0..=5 per problem statement.
        if a <= threshold {
            eligible = eligible.wrapping_add(1);
        }
    }

    eligible / 3
}

